INSERT INTO "_dic_rock_all" VALUES(913,'PEP','Pépérite - A lithified, fluidised mixture of hyaloclastite and sediment formed by the disruption and rapid chilling of magma when it is intruded into, or flows over, wet sediment. British Geological Survey Research Report RR/99/06, section 8.2.','Pépérite','C','R','AWEL','2002-01-11 00:00:00','TMCM','2019-02-15 16:38:36');
