INSERT INTO "_dic_rock_all" VALUES(3668,'MSV','Mud, sandy, gravelly [Unlithified Deposits Coding Scheme - Extended]','Gravelly sandy mud [UDCS-X]','C','U','TMCM','2020-10-02 17:07:09',NULL,NULL);
