INSERT INTO "_dic_rock_all" VALUES(3670,'SLTSDY','Silt, sandy [Obsolete code: use ZS]','Sandy silt','O','U','AWEL','2001-07-25 11:55:08','TMCM','2020-10-02 17:34:38');
INSERT INTO "_dic_rock_all" VALUES(3671,'SANDU','Sand [Obsolete code: use S]','Sand','O','N','GRBA','2000-02-24 10:00:00','TMCM','2020-10-02 17:37:03');
INSERT INTO "_dic_rock_all" VALUES(3672,'CLSA','Sand, clayey [Obsolete code: use SC]','Clayey sand','O','U','AWEL','2002-06-11 00:00:00','TMCM','2020-10-02 17:37:57');
INSERT INTO "_dic_rock_all" VALUES(3673,'SVM','Sand, gravelly, muddy [Unlithified Deposits Coding Scheme - Extended]','Muddy gravelly sand [UDCS-X]','C','U','TMCM','2020-10-02 17:39:36',NULL,NULL);
INSERT INTO "_dic_rock_all" VALUES(3674,'SMV','Sand, muddy, gravelly [Unlithified Deposits Coding Scheme - Extended]','Gravelly muddy sand [UDCS-X]','C','U','TMCM','2020-10-02 17:39:40',NULL,NULL);
INSERT INTO "_dic_rock_all" VALUES(3675,'XVHC','Gravel, shelly, clayey [Unlithified Deposits Coding Scheme - Extended] [Obsolete code: use VHC]','Clayey shelly gravel [UDCS-X]','O','U','DJLO','2009-05-06 10:42:03','TMCM','2020-08-10 15:23:22');
INSERT INTO "_dic_rock_all" VALUES(3676,'XZHS','Silt, shelly, sandy [Unlithified Deposits Coding Scheme - Extended] [Obsolete code: use ZHS]','Sandy shelly silt [UDCS-X]','O','U','DJLO','2009-05-06 10:53:39','TMCM','2020-08-10 15:32:07');
